@page "/board"
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<h1 class="mb-4">Project Board</h1>

@if (isLoading)
{
    <div class="d-flex justify-content-center my-5">
        <div class="spinner-border" role="status">
            <span class="visually-hidden">Loading...</span>
        </div>
    </div>
}
else if (errorMessage is not null)
{
    <div class="alert alert-danger" role="alert">
        <strong>Error:</strong> @errorMessage
    </div>
}
else
{
    <!-- Stats Bar -->
    <div class="row g-3 mb-4">
        <div class="col">
            <div class="card text-center">
                <div class="card-body py-2">
                    <div class="text-muted small">Total</div>
                    <div class="fw-bold fs-5">@filteredTasks.Count</div>
                </div>
            </div>
        </div>
        @foreach (var col in columns)
        {
            <div class="col">
                <div class="card text-center">
                    <div class="card-body py-2">
                        <div class="text-muted small">@col</div>
                        <div class="fw-bold fs-5">@filteredTasks.Count(t => t.Status == col)</div>
                    </div>
                </div>
            </div>
        }
        <div class="col">
            <div class="card text-center border-danger">
                <div class="card-body py-2">
                    <div class="text-muted small">Overdue</div>
                    <div class="fw-bold fs-5 text-danger">@filteredTasks.Count(t => t.DueDate < DateTime.Today)</div>
                </div>
            </div>
        </div>
    </div>

    <!-- Search Bar -->
    <div class="mb-4">
        <input type="text" class="form-control" placeholder="Search tasks by title..."
               @bind="searchText" @bind:event="oninput" />
    </div>

    <!-- Kanban Columns -->
    <div class="row g-3">
        @for (int i = 0; i < columns.Length; i++)
        {
            var colIndex = i;
            var colName = columns[colIndex];
            var colTasks = filteredTasks.Where(t => t.Status == colName).ToList();

            <div class="col-md-4">
                <div class="card h-100">
                    <div class="card-header d-flex justify-content-between align-items-center">
                        <strong>@colName</strong>
                        <span class="badge bg-secondary">@colTasks.Count</span>
                    </div>
                    <div class="card-body d-flex flex-column gap-2">
                        @foreach (var task in colTasks)
                        {
                            <div class="card shadow-sm">
                                <div class="card-body p-2">
                                    <div class="d-flex justify-content-between align-items-start mb-1">
                                        <strong class="me-2">@task.Title</strong>
                                        <span class="badge @GetPriorityClass(task.Priority)">@task.Priority</span>
                                    </div>
                                    <div class="text-muted small mb-2">
                                        @task.Assignee &middot; @task.DueDate.ToString("MMM dd")
                                    </div>
                                    <div class="d-flex gap-1">
                                        @if (colIndex > 0)
                                        {
                                            <button class="btn btn-outline-secondary btn-sm"
                                                    @onclick="() => MoveTaskAsync(task.Id, columns[colIndex - 1])">
                                                &larr; Move Left
                                            </button>
                                        }
                                        @if (colIndex < columns.Length - 1)
                                        {
                                            <button class="btn btn-outline-secondary btn-sm"
                                                    @onclick="() => MoveTaskAsync(task.Id, columns[colIndex + 1])">
                                                Move Right &rarr;
                                            </button>
                                        }
                                    </div>
                                </div>
                            </div>
                        }

                        @if (addingToColumn == colName)
                        {
                            <div class="card border-primary">
                                <div class="card-body p-2">
                                    <div class="mb-2">
                                        <input type="text" class="form-control form-control-sm" placeholder="Title"
                                               @bind="newTitle" />
                                    </div>
                                    <div class="mb-2">
                                        <input type="text" class="form-control form-control-sm" placeholder="Assignee"
                                               @bind="newAssignee" />
                                    </div>
                                    <div class="mb-2">
                                        <select class="form-select form-select-sm" @bind="newPriority">
                                            <option value="High">High</option>
                                            <option value="Medium">Medium</option>
                                            <option value="Low">Low</option>
                                        </select>
                                    </div>
                                    <div class="mb-2">
                                        <input type="date" class="form-control form-control-sm"
                                               @bind="newDueDate" />
                                    </div>
                                    <div class="d-flex gap-1">
                                        <button class="btn btn-primary btn-sm" @onclick="SaveTaskAsync">Save</button>
                                        <button class="btn btn-secondary btn-sm" @onclick="CancelAdd">Cancel</button>
                                    </div>
                                </div>
                            </div>
                        }
                    </div>
                    <div class="card-footer">
                        <button class="btn btn-outline-primary btn-sm w-100"
                                @onclick="() => StartAdd(colName)">
                            + Add Task
                        </button>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    private readonly string[] columns = ["To Do", "In Progress", "Done"];

    private List<TaskItem> allTasks = new();
    private bool isLoading = true;
    private string? errorMessage;
    private string searchText = string.Empty;

    // Add-task form state
    private string? addingToColumn;
    private string newTitle = string.Empty;
    private string newAssignee = string.Empty;
    private string newPriority = "Medium";
    private DateTime newDueDate = DateTime.Today.AddDays(7);

    private List<TaskItem> filteredTasks =>
        string.IsNullOrWhiteSpace(searchText)
            ? allTasks
            : allTasks.Where(t => t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase)).ToList();

    protected override async Task OnInitializedAsync()
    {
        try
        {
            allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
        finally
        {
            isLoading = false;
        }
    }

    private async Task MoveTaskAsync(int taskId, string newStatus)
    {
        try
        {
            await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
            var task = allTasks.First(t => t.Id == taskId);
            allTasks[allTasks.IndexOf(task)] = task with { Status = newStatus };
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
    }

    private void StartAdd(string column)
    {
        addingToColumn = column;
        newTitle = string.Empty;
        newAssignee = string.Empty;
        newPriority = "Medium";
        newDueDate = DateTime.Today.AddDays(7);
    }

    private void CancelAdd() => addingToColumn = null;

    private async Task SaveTaskAsync()
    {
        if (string.IsNullOrWhiteSpace(newTitle) || addingToColumn is null)
            return;

        try
        {
            var created = await TaskService.CreateTaskAsync(newTitle, newAssignee, newPriority, newDueDate);
            // The service creates with default status; override to match the target column
            allTasks.Add(created with { Status = addingToColumn });
            if (created.Status != addingToColumn)
            {
                await TaskService.UpdateTaskStatusAsync(created.Id, addingToColumn);
            }
            addingToColumn = null;
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
    }

    private static string GetPriorityClass(string priority) => priority switch
    {
        "High" => "bg-danger",
        "Medium" => "bg-warning text-dark",
        "Low" => "bg-success",
        _ => "bg-secondary"
    };
}

